const DEFAULT_BFF_BASE_URL = "http://agent-system-backend:8000";

export default {
  description: "讀取目前 workflow-test chat 綁定的 backend-owned system Workflow context。",
  input: {"type":"object","properties":{"project":{"type":"string","minLength":1,"maxLength":80,"description":"目前 project 名稱"}},"required":["project"],"additionalProperties":false},
  async execute(args, context) {

    const baseURL = (process.env.AGENT_SYSTEM_BFF_BASE_URL || DEFAULT_BFF_BASE_URL).replace(/\/+$/, "");
    const endpoint = new URL(
      "/bff/workflow-resources/test-chat/" + encodeURIComponent(context.sessionID) + "/context", baseURL);
    endpoint.searchParams.set("project", args.project);
    const response = await fetch(endpoint, { headers: { "x-agent-system-workspace": args.project }, signal: AbortSignal.timeout(15_000) });
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || !isRecord(payload) || !isRecord(payload.input)) {
      throw new Error("backend 沒有回傳目前 workflow-test chat 的 canonical context。");
    }
    return { content: JSON.stringify({
        input: payload.input,
        project: payload.project,
        workflowID: payload.workflowID,
        workflowV3SerializationContract: payload.workflowV3SerializationContract,
      }), metadata: { title: "Backend-owned Workflow context" } };
  },
};

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

const resourceTypes = new Set(["agent", "command", "skill", "tool", "mcp", "plugin"]);
const nodeTypes = {
  agent: "resource.agent",
  command: "resource.command",
  skill: "resource.skill",
  tool: "resource.tool",
  mcp: "resource.mcp",
  plugin: "resource.plugin",
};
const registryName = /^[A-Za-z0-9_.-]{1,100}$/;
const envReference = /^\{env:[A-Z_][A-Z0-9_]*\}$/;
const placeholderWord = /\b(?:TODO|TBD|PLACEHOLDER)\b/i;
const placeholder = /<(?:request|value|API_KEY|ACCESS_TOKEN|SECRET|TOKEN|YOUR_[A-Z0-9_]{1,64}|(?:insert|INSERT)(?:[-_ ][A-Za-z0-9_. -]{0,64})?|\.\.\.)>|\{\{/;
const safeRelativePath = /^(?![\\/])(?!.*(?:^|[\\/])\.\.(?:[\\/]|$))[A-Za-z0-9._\\/-]+$/;
const skillName = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const supportedWorkflowSchemas = new Set(["agent-system.workflow.v1", "agent-system.workflow.v2", "agent-system.workflow.v3"]);
const inventoryGroups = ["agents", "tools", "skills", "plugins", "mcp", "commands"];
const DEFAULT_BFF_BASE_URL = "http://agent-system-backend:8000";
const BACKEND_WORKFLOW_REFERENCE = "__BACKEND_SESSION_WORKFLOW__";

export default {
  description: "Deterministically validate one typed resource envelope against backend-owned Workflow V3 context.",
  input: {
    type: "object",
    properties: {
      resourceType: { type: "string", minLength: 1, maxLength: 20 },
      targetNodeID: { type: "string", minLength: 1, maxLength: 100 },
      resourceJson: { type: "string", maxLength: 600000 },
      workflowJson: { type: "string", maxLength: 950000 },
      project: { type: "string", minLength: 1, maxLength: 80 },
      request: { type: "string", maxLength: 20000 },
    },
    required: ["resourceType", "targetNodeID", "resourceJson", "workflowJson", "project", "request"],
    additionalProperties: false,
  },
  async execute(rawArgs, context) {
    const args = await resolveBackendWorkflowReference(rawArgs, context);
    if (!args) return failure("WORKFLOW_RESOURCE_CONTEXT_INVALID", "The backend session Workflow context was unavailable.");
    const expected = normalizeResourceType(args.resourceType);
    if (!expected || !resourceTypes.has(expected)) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_TYPE_INVALID", "resourceType is unsupported.", { resourceType: args.resourceType });
    }

    let candidate;
    let workflow;
    try {
      candidate = JSON.parse(args.resourceJson);
      workflow = JSON.parse(args.workflowJson);
    } catch {
      return failure("WORKFLOW_RESOURCE_OUTPUT_JSON_INVALID", "resourceJson and workflowJson must be valid JSON.");
    }
    const envelopeKeys = ["resourceType", "resource", "summary", "validation"];
    const allowedEnvelopeKeys = expected === "agent" ? [...envelopeKeys, "graph", "skills", "skillReferences"] : envelopeKeys;
    if (!isRecord(candidate)
      || !hasRequiredKeys(candidate, envelopeKeys)
      || !hasOnlyKeys(candidate, allowedEnvelopeKeys)) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_ENVELOPE_INVALID", "Output must contain the required resource envelope and only optional Agent skills or skillReferences arrays.");
    }
    const actual = normalizeResourceType(candidate.resourceType);
    if (actual !== expected) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_TYPE_MISMATCH", "Output resourceType does not match the requested type.", { expected, actual });
    }
    if (typeof candidate.summary !== "string" || !candidate.summary.trim() || candidate.summary.length > 2000) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_SUMMARY_INVALID", "summary must be a non-empty string of at most 2000 characters.");
    }
    if (containsSecretLiteral(candidate.summary)) {
      return failure("WORKFLOW_RESOURCE_SECRET_DETECTED", "summary contains a possible plaintext secret.");
    }
    if (!isRecord(candidate.validation)
      || !hasExactKeys(candidate.validation, ["valid", "errors", "warnings"])
      || typeof candidate.validation.valid !== "boolean"
      || !isStringArray(candidate.validation.errors)
      || !isStringArray(candidate.validation.warnings)) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_VALIDATION_INVALID", "validation must contain valid, errors, and warnings with exact types.");
    }
    if (candidate.validation.valid !== true || candidate.validation.errors.length > 0) {
      return failure("WORKFLOW_RESOURCE_OUTPUT_VALIDATION_INVALID", "Generated resource validation failed.", {
        errors: boundedDiagnostics(candidate.validation.errors),
        warnings: boundedDiagnostics(candidate.validation.warnings),
      });
    }
    if (!isRecord(workflow) || !supportedWorkflowSchemas.has(workflow.schemaVersion) || !Array.isArray(workflow.nodes) || !Array.isArray(workflow.edges)) {
      return failure("WORKFLOW_RESOURCE_CONTEXT_INVALID", "workflowJson must be a complete supported Workflow object.");
    }
    const target = workflow.nodes.find((node) => isRecord(node) && node.id === args.targetNodeID);
    if (!isRecord(target) || !isRecord(target.data) || target.type !== nodeTypes[expected] || target.data.mode !== "managed") {
      return failure("WORKFLOW_RESOURCE_TARGET_INVALID", "targetNodeID does not match resourceType.", { targetNodeID: args.targetNodeID });
    }
    if (target.data.scope === "project" && workflow.project !== args.project) {
      return failure("WORKFLOW_RESOURCE_CONTEXT_INVALID", "Project-scoped targets must belong to the authoritative project.");
    }
    if (!isRecord(candidate.resource)) {
      return failure("WORKFLOW_RESOURCE_SHAPE_INVALID", "resource must be an object.");
    }
    const resource = candidate.resource;
    const expectedKeys = resourceShapeKeys(expected, resource);
    if (!expectedKeys || !hasExactKeys(resource, expectedKeys)) {
      return failure("WORKFLOW_RESOURCE_SHAPE_INVALID", "resource keys do not match the requested resource type.");
    }
    if (typeof resource.name !== "string" || !registryName.test(resource.name)
      || (resource.name !== target.data.name && (expected !== "agent" || !agentNameChangeRequested(args.request, target.data.name, resource.name)))
      || resource.scope !== target.data.scope
      || (resource.scope !== "project" && resource.scope !== "global")) {
      return failure("WORKFLOW_RESOURCE_IDENTITY_INVALID", "resource name and scope must match the target node.");
    }
    if (expected === "agent" && resource.name !== target.data.name && workflow.nodes.some((node) => isRecord(node)
      && node !== target
      && node.type === nodeTypes.agent
      && isRecord(node.data)
      && node.data.name === resource.name
      && node.data.scope === resource.scope)) {
      return failure("WORKFLOW_RESOURCE_IDENTITY_CONFLICT", "resource name conflicts with another Workflow Agent.");
    }
    if (containsSecretLiteral(resource)) {
      return failure("WORKFLOW_RESOURCE_SECRET_DETECTED", "resource contains a possible plaintext secret.");
    }
    const unchangedBackendContent = expected === "agent"
      && resource.name === target.data.name
      && resource.content === target.data.content;
    if (!unchangedBackendContent && (placeholderWord.test(JSON.stringify(resource)) || placeholder.test(JSON.stringify(resource)))) {
      return failure("WORKFLOW_RESOURCE_PLACEHOLDER", "resource contains a placeholder.");
    }

    let generatedSkillNames = [];
    if (expected === "agent" && candidate.skills !== undefined) {
      const generatedSkills = validateGeneratedSkills(candidate.skills, workflow, target);
      if (generatedSkills.failure) return failure(generatedSkills.failure.code, generatedSkills.failure.message, generatedSkills.failure.details);
      generatedSkillNames = generatedSkills.names;
    }

    let referencedSkillNames = [];
    if (expected === "agent" && candidate.skillReferences !== undefined) {
      const references = await validateSkillReferences(candidate.skillReferences, workflow, target, args, context, generatedSkillNames);
      if (references.failure) return failure(references.failure.code, references.failure.message, references.failure.details);
      referencedSkillNames = references.names;
    }

    let validationWorkflow = workflow;
    if (expected === "agent" && candidate.graph !== undefined) {
      const graph = await validateAgentGraph(candidate.graph, workflow, target, resource, args, context);
      if (graph.failure) return failure(graph.failure.code, graph.failure.message, graph.failure.details);
      validationWorkflow = graph.workflow;
    }

    const semanticFailure = unchangedBackendContent
      ? undefined
      : validateResource(expected, resource, validationWorkflow, target, args.request, [...generatedSkillNames, ...referencedSkillNames]);
    if (semanticFailure) return failure(semanticFailure.code, semanticFailure.message, semanticFailure.details);

    return {
      content: JSON.stringify({
        resourceType: expected,
        resource,
        ...(expected === "agent" && candidate.graph !== undefined ? { graph: candidate.graph } : {}),
        ...(expected === "agent" && candidate.skills !== undefined ? { skills: candidate.skills } : {}),
        ...(expected === "agent" && candidate.skillReferences !== undefined ? { skillReferences: candidate.skillReferences } : {}),
        summary: candidate.summary,
        validation: {
          valid: true,
          errors: [],
          warnings: boundedDiagnostics(candidate.validation.warnings),
        },
      }),
      metadata: { title: "Validated typed resource output" },
    };
  },
};

async function resolveBackendWorkflowReference(args, context) {
  if (args.workflowJson !== BACKEND_WORKFLOW_REFERENCE) return args;
  if (!context || typeof context.sessionID !== "string" || !context.sessionID || !args.project) return undefined;
  const baseURL = (process.env.AGENT_SYSTEM_BFF_BASE_URL || DEFAULT_BFF_BASE_URL).replace(/\/+$/, "");
  const endpoint = new URL(
    "/bff/workflow-resources/test-chat/" + encodeURIComponent(context.sessionID) + "/context", baseURL);
  endpoint.searchParams.set("project", args.project);
  try {
    const response = await fetch(endpoint, {
      headers: { "x-agent-system-workspace": args.project },
      signal: AbortSignal.timeout(15_000),
    });
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || !isRecord(payload) || !isRecord(payload.input) || !isRecord(payload.input.workflow)) return undefined;
    return { ...args, workflowJson: JSON.stringify(payload.input.workflow) };
  } catch {
    return undefined;
  }
}

function validateResource(resourceType, resource, workflow, target, request, generatedSkillNames = []) {
  if (resourceType === "mcp") return validateMcp(resource.config);
  if (resourceType === "plugin" && resource.config !== undefined) return validateRemotePlugin(resource.config, request);
  if (typeof resource.content !== "string" || !resource.content.trim() || resource.content.length > 524288) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_REQUIRED", message: "A bounded non-empty content string is required." };
  }
  if (resourceType === "agent") return validateAgent(resource, workflow, target, request, generatedSkillNames);
  if (resourceType === "command") return validateCommand(resource, workflow, target, request);
  if (resourceType === "skill") return validateSkill(resource);
  if (resourceType === "tool") return validateTool(resource.content);
  if (resourceType === "plugin") {
    if (!/\bexport\s+default\b/.test(resource.content)) {
      return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Local Plugin content must contain a default export." };
    }
    return undefined;
  }
  return { code: "WORKFLOW_RESOURCE_OUTPUT_TYPE_INVALID", message: "resourceType is unsupported." };
}

function validateAgent(resource, workflow, target, request, generatedSkillNames) {
  const frontmatter = parseFrontmatter(resource.content);
  const nativeRules = frontmatter ? parseNativePermissionRules(frontmatter.lines) : undefined;
  const unsupportedFields = frontmatter ? unsupportedNativeV2AgentFields(frontmatter.lines) : [];
  if (unsupportedFields.length > 0) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: `New managed Agent native V2 frontmatter contains unsupported V1 field(s): ${unsupportedFields.join(", ")}.` };
  }
  if (!frontmatter
    || hasUnsupportedYamlSyntax(frontmatter.lines)
    || hasAmbiguousScalarFields(frontmatter.lines, ["description", "mode", "model", "variant", "disabled", "disable"])
    || !nativeRules?.valid
    || !scalar(frontmatter.lines, "description")) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "New managed Agent content requires native V2 permissions, no V1-only fields, and a non-empty description." };
  }
  const entryEdges = workflow.edges.filter((edge) => isRecord(edge)
    && edge.kind === "capability"
    && edge.target === target.id
    && edge.targetHandle === "agent"
    && workflow.nodes.some((node) => isRecord(node) && node.id === edge.source && node.type === "resource.command"));
  const parentEdges = workflow.edges.filter((edge) => isRecord(edge) && edge.kind === "delegation" && edge.target === target.id);
  const expectedMode = entryEdges.length === 1 && parentEdges.length === 0
    ? "primary"
    : entryEdges.length === 0 && parentEdges.length > 0
      ? "subagent"
      : undefined;
  if (!expectedMode || scalar(frontmatter.lines, "mode") !== expectedMode) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Agent frontmatter mode does not match its graph role." };
  }
  const childNames = workflow.edges
    .filter((edge) => isRecord(edge) && edge.kind === "delegation" && edge.source === target.id)
    .map((edge) => workflow.nodes.find((node) => isRecord(node) && node.id === edge.target)?.data)
    .filter(isRecord)
    .map((data) => data.name)
    .filter((name) => typeof name === "string");
  const permissionIssue = validateNativeAgentPermissions(frontmatter, nativeRules.rules, workflow, target, childNames, generatedSkillNames);
  if (permissionIssue) return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: permissionIssue };
  if (!preservesRuntimeFields(target, frontmatter.lines, request)) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Agent model and variant may change only when the request names the exact new value." };
  }
  return undefined;
}

function unsupportedNativeV2AgentFields(lines) {
  const unsupported = new Set(["name", "permission", "tools", "skills", "temperature", "top_p", "model", "variant", "prompt", "disable"]);
  return lines.flatMap((line) => {
    if (leadingSpaces(line) !== 0) return [];
    const match = line.trim().match(/^(?:"([^\"]+)"|'([^']+)'|([A-Za-z][A-Za-z0-9_-]*))\s*:/);
    const key = match?.[1] ?? match?.[2] ?? match?.[3];
    return key && unsupported.has(key) ? [key] : [];
  });
}

function parseNativePermissionRules(lines) {
  const starts = lines.flatMap((line, index) => leadingSpaces(line) === 0 && /^permissions\s*:/.test(line.trim()) ? [index] : []);
  if (starts.length !== 1 || lines[starts[0]]?.trim() !== "permissions:") return { valid: false, rules: [] };
  const start = starts[0];
  let end = lines.length;
  for (let index = start + 1; index < lines.length; index += 1) {
    if (lines[index]?.trim() && leadingSpaces(lines[index]) === 0) {
      end = index;
      break;
    }
  }
  const rules = [];
  let current;
  let invalid = false;
  const finish = () => {
    if (!current) return;
    if (Object.keys(current).length !== 3 || !["action", "resource", "effect"].every((key) => typeof current[key] === "string" && current[key])) invalid = true;
    else if (!["allow", "ask", "deny"].includes(current.effect)) invalid = true;
    else rules.push(current);
    current = undefined;
  };
  for (let index = start + 1; index < end; index += 1) {
    const line = lines[index] ?? "";
    if (!line.trim() || line.trim().startsWith("#")) continue;
    const indent = leadingSpaces(line);
    const item = indent === 2 ? line.trim().match(/^-\s+action:\s*(.*?)\s*$/) : undefined;
    if (item) {
      finish();
      const action = simpleScalar(item[1] ?? "");
      if (!action) invalid = true;
      current = action ? { action } : {};
      continue;
    }
    const field = indent === 4 ? line.trim().match(/^(resource|effect):\s*(.*?)\s*$/) : undefined;
    if (!field || !current || Object.prototype.hasOwnProperty.call(current, field[1])) {
      invalid = true;
      continue;
    }
    const value = simpleScalar(field[2] ?? "");
    if (!value) invalid = true;
    else current[field[1]] = value;
  }
  finish();
  return { valid: !invalid && rules.length > 0, rules };
}

function validateNativeAgentPermissions(frontmatter, rules, workflow, target, childNames, generatedSkillNames = []) {
  const wildcardDenies = rules.filter((rule) => rule.action === "*" && rule.resource === "*" && rule.effect === "deny");
  if (wildcardDenies.length !== 1 || rules[0] !== wildcardDenies[0]) return "Agent permissions must begin with one wildcard deny rule.";
  if (rules.some((rule) => ["write", "patch", "apply_patch", "bash", "task"].includes(rule.action))) {
    return "Agent permissions must use native V2 action names, not V1 aliases.";
  }
  if (!frontmatter.body.includes("error_log_recent")
    || !/(?:error|failure|錯誤|失敗)/i.test(frontmatter.body)
    || !/(?:call|invoke|呼叫|调用)/i.test(frontmatter.body)) {
    return "Agent instructions must call error_log_recent before returning an error.";
  }

  const expected = new Set(["error_log_recent|*"]);
  for (const child of childNames) expected.add(`subagent|${child}`);
  const skillNames = [...generatedSkillNames];
  for (const edge of workflow.edges) {
    if (!isRecord(edge) || edge.kind !== "capability" || edge.target !== target.id || edge.targetHandle !== "capability") continue;
    const source = workflow.nodes.find((node) => isRecord(node) && node.id === edge.source);
    if (!isRecord(source) || !isRecord(source.data) || typeof source.data.name !== "string") continue;
    if (source.type === "resource.tool") expected.add(`${source.data.name}|*`);
    else if (source.type === "resource.mcp") {
      if (!Array.isArray(source.data.toolNames)
        || source.data.toolNames.length === 0
        || source.data.toolNames.some((toolName) => typeof toolName !== "string" || !toolName || toolName.includes("*"))) {
        return "MCP capabilities require a non-empty exact tool selection.";
      }
      for (const toolName of source.data.toolNames) expected.add(`${source.data.name}_${toolName}|*`);
    }
    else if (source.type === "resource.skill") skillNames.push(source.data.name);
  }
  for (const skillName of skillNames) expected.add(`skill|${skillName}`);

  for (const rule of rules) {
    if (rule.effect !== "allow" && rule.effect !== "ask") continue;
    if (!expected.has(`${rule.action}|${rule.resource}`)) return `Agent permissions cannot allow unconnected capability ${rule.action}:${rule.resource}.`;
    if (rule.action === "subagent" && rule.effect !== "allow") return "Direct child delegation must use an allow permission.";
  }
  for (const entry of expected) {
    const [action, resource] = entry.split("|");
    const effect = nativePermissionEffect(rules, action, resource);
    if (effect !== "allow" && (action === "subagent" || action === "error_log_recent" || effect !== "ask")) return `Agent permissions must allow direct capability ${action}:${resource}.`;
  }
  return undefined;
}

function nativePermissionEffect(rules, action, resource) {
  let effect = "deny";
  for (const rule of rules) {
    if ((rule.action === "*" || rule.action === action) && nativeResourceMatches(rule.resource, resource)) effect = rule.effect;
  }
  return effect;
}

function nativeResourceMatches(pattern, resource) {
  return new RegExp(`^${pattern.split("*").map(escapeRegExp).join(".*")}$`).test(resource);
}

function validateCommand(resource, workflow, target, request) {
  const frontmatter = parseFrontmatter(resource.content);
  const entries = workflow.edges.filter((edge) => isRecord(edge)
    && edge.kind === "capability"
    && edge.source === target.id
    && edge.targetHandle === "agent");
  const entryAgent = entries.length === 1
    ? workflow.nodes.find((node) => isRecord(node) && node.id === entries[0].target)
    : undefined;
  if (!frontmatter
    || hasUnsupportedYamlSyntax(frontmatter.lines)
    || hasAmbiguousScalarFields(frontmatter.lines, ["description", "agent", "model", "variant"])
    || !scalar(frontmatter.lines, "description")
    || !isRecord(entryAgent) || !isRecord(entryAgent.data)
    || scalar(frontmatter.lines, "agent") !== entryAgent.data.name
    || !frontmatter.body.includes("$ARGUMENTS")) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Command content requires description, the exact entry Agent, and $ARGUMENTS." };
  }
  if (!preservesRuntimeFields(target, frontmatter.lines, request)) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Command model and variant may change only when the request names the exact new value." };
  }
  return undefined;
}

function preservesRuntimeFields(target, generatedLines, request) {
  const currentContent = typeof target.data.content === "string" ? target.data.content : undefined;
  const current = currentContent ? parseFrontmatter(currentContent) : undefined;
  if (currentContent && !current) return false;
  return ["model", "variant"].every((key) => {
    const currentField = current ? currentScalar(current.lines, key) : { valid: true, value: "" };
    const generatedValue = scalar(generatedLines, key);
    return currentField.valid
      && (currentField.value === generatedValue || runtimeFieldChangeRequested(request, key, generatedValue));
  });
}

function runtimeFieldChangeRequested(request, key, generatedValue) {
  if (typeof request !== "string") return false;
  const field = key === "model" ? "(?:\\bmodel\\b|模型)" : "(?:\\bvariant\\b|變體|变体)";
  const negative = "(?:\\b(?:do\\s+not|don't|never)\\b|不得|不要|不可)";
  const keep = "(?:\\b(?:keep|preserve)\\b|保留)";
  const change = "(?:\\b(?:set|change|update|replace|switch|use)\\b|改成|修改|變更|更新|設定|指定|使用|切換)";
  const remove = "(?:\\b(?:remove|delete|clear|unset)\\b|移除|刪除|删除|清除)";
  const negated = new RegExp(
    `${negative}\\s*(?:${change}|${remove})?\\s*(?:the\\s+)?${field}`
      + `|${field}\\s*(?:must\\s+)?${negative}`
      + `|${keep}\\s*(?:(?:the|current)\\s+)?${field}`
      + `|\\bwithout\\s+(?:changing|setting|updating|replacing|removing)\\s+(?:the\\s+)?${field}`,
    "i",
  );
  if (negated.test(request)) return false;
  if (!generatedValue) {
    return new RegExp(`${remove}\\s+(?:the\\s+)?${field}|${field}\\s+${remove}`, "i").test(request);
  }
  const value = `${escapeRegExp(generatedValue)}(?=$|[^A-Za-z0-9._/-]|\\.(?=\\s|$))`;
  return new RegExp(
    `${change}\\s+(?:the\\s+)?${field}\\s*(?:(?:to|as|into)\\s+)?["']?${value}`
      + `|${field}\\s+${change}\\s*(?:(?:to|as|into)\\s+)?["']?${value}`,
    "i",
  ).test(request);
}

function agentNameChangeRequested(request, currentName, generatedName) {
  if (currentName === generatedName || typeof request !== "string") return currentName === generatedName;
  const exactName = new RegExp(`(?:^|[^A-Za-z0-9_.-])${escapeRegExp(generatedName)}(?=$|[^A-Za-z0-9_.-])`);
  if (!exactName.test(request) || /(?:keep|preserve|unchanged|do not change|保留|不變|不變更)\s*(?:the\s+)?(?:Agent\s+)?(?:name|名稱)/i.test(request)) return false;
  if (/(?:\b(?:don't|do not|never|must not|cannot|can't)\b|不要|不得|不可|請勿|不應)/i.test(request)
    && /(?:\b(?:rename|change|update|replace|set)\b|(?:Agent\s+)?(?:name|名稱)|(?:將|把))/i.test(request)) return false;
  return [
    new RegExp(`(?:rename|change|update|replace|set)\\s+(?:the\\s+)?(?:Agent\\s+)?name\\s*(?:to|as|into)?\\s*["']?${escapeRegExp(generatedName)}(?=$|[^A-Za-z0-9_.-])`, "i"),
    new RegExp(`(?:Agent\\s+)?(?:name|名稱)\\s*(?:to|as|into|改成|變更為|更新為|設定為|指定為)\\s*["']?${escapeRegExp(generatedName)}(?=$|[^A-Za-z0-9_.-])`, "i"),
    new RegExp(`(?:將|把)\\s*(?:Agent\\s*)?(?:name|名稱)\\s*(?:改成|變更為|更新為|設定為|指定為)\\s*["']?${escapeRegExp(generatedName)}(?=$|[^A-Za-z0-9_.-])`, "i"),
  ].some((pattern) => pattern.test(request));
}

function validateSkill(resource) {
  const frontmatter = parseFrontmatter(resource.content);
  if (!frontmatter
    || hasUnsupportedYamlSyntax(frontmatter.lines)
    || hasAmbiguousScalarFields(frontmatter.lines, ["name", "description"])
    || scalar(frontmatter.lines, "name") !== resource.name
    || !scalar(frontmatter.lines, "description")
    || !frontmatter.body.trim()) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Skill content requires matching name, description, and non-empty instructions." };
  }
  if (resource.files !== undefined) {
    if (!isRecord(resource.files) || Object.keys(resource.files).length > 100) {
      return { code: "WORKFLOW_RESOURCE_FILES_INVALID", message: "Skill files must be a bounded object." };
    }
    let size = 0;
    for (const [path, content] of Object.entries(resource.files)) {
      if (!safeRelativePath.test(path) || path.replace(/\\/g, "/").toLowerCase() === "skill.md" || typeof content !== "string") {
        return { code: "WORKFLOW_RESOURCE_FILES_INVALID", message: "Skill file paths and contents are invalid." };
      }
      size += path.length + content.length;
    }
    if (size > 524288) return { code: "WORKFLOW_RESOURCE_FILES_INVALID", message: "Skill files exceed the size limit." };
  }
  return undefined;
}

function validateGeneratedSkills(value, workflow, target) {
  if (!Array.isArray(value) || value.length < 1 || value.length > 20) {
    return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Agent skills must contain 1-20 local Skill resources." } };
  }
  const names = [];
  const identities = new Set();
  for (const skill of value) {
    if (!isRecord(skill)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Each Agent Skill must be an object." } };
    }
    const expectedKeys = resourceShapeKeys("skill", skill);
    if (!expectedKeys || !hasExactKeys(skill, expectedKeys)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Generated Skill keys do not match the local managed Skill shape." } };
    }
    if (typeof skill.name !== "string" || skill.name.length > 64 || !skillName.test(skill.name)
      || skill.scope !== target.data.scope
      || (skill.scope !== "project" && skill.scope !== "global")) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Generated Skill names and scopes must match the target Agent policy." } };
    }
    const identity = `${skill.scope}:${skill.name}`;
    if (identities.has(identity)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Generated Skills must not contain duplicate identities." } };
    }
    identities.add(identity);
    if (workflow.nodes.some((node) => isRecord(node)
      && node.type === "resource.skill"
      && isRecord(node.data)
      && node.data.name === skill.name
      && node.data.scope === skill.scope)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Generated Skill identity already exists in the current Workflow." } };
    }
    if (containsSecretLiteral(skill) || placeholderWord.test(JSON.stringify(skill)) || placeholder.test(JSON.stringify(skill))) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Generated Skill contains a secret or placeholder." } };
    }
    const semanticFailure = validateSkill(skill);
    if (semanticFailure) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: semanticFailure.message, details: semanticFailure.details } };
    }
    names.push(skill.name);
  }
  return { names };
}

async function validateSkillReferences(value, workflow, target, args, context, generatedSkillNames) {
  if (!Array.isArray(value) || value.length < 1 || value.length > 20) {
    return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Agent Skill references must contain 1-20 existing Skill resources." } };
  }
  const inventoryResult = await fetchSessionInventory(args.project, context);
  if (inventoryResult.failure) return inventoryResult;
  const inventorySkills = inventoryResult.inventory.resources.skills;
  const identities = new Set(generatedSkillNames.map((name) => `${target.data.scope}:${name}`));
  const names = [];
  for (const reference of value) {
    if (!isRecord(reference) || !hasExactKeys(reference, ["name", "scope"])) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_INVALID", message: "Skill references must contain only name and scope." } };
    }
    if (typeof reference.name !== "string" || reference.name.length > 64 || !skillName.test(reference.name)
      || (reference.scope !== "project" && reference.scope !== "global")) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_INVALID", message: "Skill reference names and scopes are invalid." } };
    }
    if (!hasExplicitSkillReferenceIntent(args.request, reference.name)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_INVALID", message: `Request does not explicitly ask to use existing Skill ${reference.name}.` } };
    }
    if (reference.scope === "project" && (target.data.scope !== "project" || workflow.project !== args.project)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_INVALID", message: "Project Skill references must match the target project." } };
    }
    const identity = `${reference.scope}:${reference.name}`;
    if (identities.has(identity)) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: "Managed and existing Skills must not contain duplicate identities." } };
    }
    identities.add(identity);
    const inventoryResource = inventorySkills.find((resource) => isRecord(resource)
      && resource.type === "resource.skill"
      && resource.name === reference.name
      && resource.scope === reference.scope);
    if (!inventoryResource) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_NOT_FOUND", message: `Existing Skill reference ${reference.name} was not found in the canonical inventory.` } };
    }
    if (!Array.isArray(inventoryResource.sources)
      || !inventoryResource.sources.some((source) => source === "config" || source === "registry" || source === "runtime")) {
      return skillReferenceEligibilityFailure(reference);
    }
    const currentNode = workflow.nodes.find((node) => isRecord(node)
      && node.type === "resource.skill"
      && isRecord(node.data)
      && node.data.name === reference.name
      && node.data.scope === reference.scope);
    if (currentNode && (!isRecord(currentNode.data) || currentNode.data.mode !== "reference")) {
      return { failure: { code: "WORKFLOW_RESOURCE_SKILLS_INVALID", message: `Existing Skill ${reference.name} conflicts with a managed Workflow resource.` } };
    }
    names.push(reference.name);
  }
  return { names };
}

function skillReferenceEligibilityFailure(reference) {
  return {
    failure: {
      code: "WORKFLOW_RESOURCE_SKILL_REFERENCE_INELIGIBLE",
      message: `Existing Skill reference ${reference.name} is not eligible under the canonical source policy.`,
      details: [`${reference.scope}:${reference.name}`, "source"],
    },
  };
}

async function validateAgentGraph(value, workflow, target, candidateResource, args, context) {
  if (!isRecord(value) || !hasExactKeys(value, ["resources", "relationships"])
    || !Array.isArray(value.resources) || !Array.isArray(value.relationships)
    || value.resources.length > 100 || value.relationships.length > 200) {
    return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph must contain bounded resources and relationships arrays." } };
  }
  const inventoryResult = await fetchSessionInventory(args.project, context);
  if (inventoryResult.failure) return inventoryResult;

  const nodes = [...workflow.nodes];
  const edges = [...workflow.edges];
  const identityToNode = new Map();
  for (const node of nodes) {
    const identity = graphNodeIdentity(node);
    if (identity) identityToNode.set(identity, node);
  }
  const candidateTarget = {
    ...target,
    data: { ...target.data, name: candidateResource.name, scope: candidateResource.scope },
  };
  const targetIdentities = new Set([graphNodeIdentity(target), graphNodeIdentity(candidateTarget)].filter(Boolean));
  identityToNode.set(graphNodeIdentity(candidateTarget), candidateTarget);
  const graphIdentities = new Set();
  const graphNodes = [];
  for (const [index, rawResource] of value.resources.entries()) {
    const resource = normalizeGraphResource(rawResource, index);
    if (resource.failure) return resource;
    const identity = graphResourceIdentity(resource.value);
    if (targetIdentities.has(identity)) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph cannot redefine its managed target resource." } };
    }
    if (graphIdentities.has(identity)) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: `Agent graph contains duplicate resource identity ${identity}.` } };
    }
    graphIdentities.add(identity);
    if (resource.value.scope === "project" && (workflow.project !== args.project || target.data.scope !== "project")) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_SCOPE_INVALID", message: "Project graph resources must match the authoritative target project." } };
    }

    const currentNode = identityToNode.get(identity);
    if (resource.value.mode === "reference") {
      const inventoryResource = findInventoryResource(inventoryResult.inventory, resource.value);
      if (!inventoryResource || !hasInventorySources(inventoryResource)
        || !hasExplicitGraphResourceIntent(args.request, resource.value.name)) {
        return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_REFERENCE_NOT_FOUND", message: `Reference resource ${identity} was not proven by the canonical inventory and request.` } };
      }
      if (currentNode && (!isRecord(currentNode.data) || currentNode.data.mode !== "reference")) {
        return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_REFERENCE_CONFLICT", message: `Reference resource ${identity} conflicts with a managed Workflow resource.` } };
      }
    } else if (currentNode && (!isRecord(currentNode.data) || currentNode.data.mode !== "managed")) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_MANAGED_CONFLICT", message: `Managed resource ${identity} conflicts with a reference Workflow resource.` } };
    } else if (currentNode && resource.value.type === "resource.agent") {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_AGENT_UPDATE_NOT_ALLOWED", message: `Managed child Agent ${identity} cannot be updated through Agent graph.` } };
    } else if (!hasExplicitManagedGraphResourceIntent(args.request, resource.value.name, Boolean(currentNode))) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_UPDATE_NOT_REQUESTED", message: `Managed graph resource ${identity} was not explicitly requested.` } };
    }

    const node = currentNode && resource.value.mode === "managed"
      ? { ...currentNode, data: graphResourceData(resource.value) }
      : currentNode ?? {
      id: `agent-writer-graph-${index}`,
      type: resource.value.type,
      data: graphResourceData(resource.value),
    };
    if (!currentNode) {
      nodes.push(node);
      identityToNode.set(identity, node);
    } else if (resource.value.mode === "managed") {
      const currentIndex = nodes.findIndex((candidate) => candidate.id === currentNode.id);
      if (currentIndex >= 0) nodes[currentIndex] = node;
      identityToNode.set(identity, node);
    }
    graphNodes.push({ identity, resource: resource.value, node });
  }

  const relationshipIdentities = new Set();
  const connectedGraphIdentities = new Set();
  for (const [index, rawRelationship] of value.relationships.entries()) {
    if (!isRecord(rawRelationship) || !hasExactKeys(rawRelationship, ["kind", "source", "target"])) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: `Agent graph relationship ${index} has an invalid shape.` } };
    }
    const source = normalizeGraphIdentity(rawRelationship.source);
    const targetIdentity = normalizeGraphIdentity(rawRelationship.target);
    if (source.failure || targetIdentity.failure) {
      const invalidEndpoint = source.failure ? "source" : "target";
      const invalidValue = source.failure ? rawRelationship.source : rawRelationship.target;
      return {
        failure: {
          code: "WORKFLOW_RESOURCE_GRAPH_INVALID",
          message: `Agent graph relationship ${index} has an invalid endpoint.`,
          details: graphRelationshipEndpointDetails(invalidValue, index, invalidEndpoint),
        },
      };
    }
    const sourceNode = identityToNode.get(graphResourceIdentity(source.value));
    const targetNode = identityToNode.get(graphResourceIdentity(targetIdentity.value));
    if (!sourceNode || !targetNode) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: `Agent graph relationship ${index} references an unknown resource.` } };
    }
    if (sourceNode === targetNode) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph relationships cannot self-reference." } };
    }
    const relationshipKey = `${rawRelationship.kind}:${sourceNode.id}:${targetNode.id}`;
    if (relationshipIdentities.has(relationshipKey)) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph relationships must be unique." } };
    }
    relationshipIdentities.add(relationshipKey);
    let edge;
    if (rawRelationship.kind === "capability") {
      if (!new Set(["resource.skill", "resource.tool", "resource.mcp", "resource.plugin"]).has(sourceNode.type)
        || targetNode.type !== "resource.agent" || targetNode.data.mode !== "managed") {
        return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_EDGE_INVALID", message: "Capability relationships must point from a Skill, Tool, MCP, or Plugin to a managed Agent." } };
      }
      edge = { id: `agent-writer-graph-edge-${index}`, source: sourceNode.id, target: targetNode.id, kind: "capability", sourceHandle: "capability", targetHandle: "capability" };
    } else if (rawRelationship.kind === "delegation") {
      if (sourceNode.type !== "resource.agent" || sourceNode.data.mode !== "managed"
        || targetNode.type !== "resource.agent") {
        return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_EDGE_INVALID", message: "Delegation relationships require a managed Agent parent and an Agent child." } };
      }
      edge = { id: `agent-writer-graph-edge-${index}`, source: sourceNode.id, target: targetNode.id, kind: "delegation", sourceHandle: "delegation", targetHandle: "agent" };
    } else {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_EDGE_INVALID", message: "Agent graph supports only capability and delegation relationships." } };
    }
    if (!edges.some((candidate) => candidate.kind === edge.kind && candidate.source === edge.source && candidate.target === edge.target)) {
      edges.push(edge);
    }
    connectedGraphIdentities.add(graphResourceIdentity(source.value));
    connectedGraphIdentities.add(graphResourceIdentity(targetIdentity.value));
  }

  for (const graphNode of graphNodes) {
    if (!connectedGraphIdentities.has(graphNode.identity)) {
      return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: `Agent graph resource ${graphNode.identity} is not connected.` } };
    }
    if (graphNode.resource.mode === "managed") {
      const resourceType = graphNode.resource.type.slice("resource.".length);
      const payload = { ...graphNode.node.data };
      delete payload.mode;
      const semanticFailure = validateResource(resourceType, payload, { ...workflow, nodes, edges }, graphNode.node, args.request, []);
      if (semanticFailure) return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_RESOURCE_INVALID", message: semanticFailure.message, details: semanticFailure.details } };
    }
  }

  if (hasDelegationCycle(nodes, edges)) {
    return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_CYCLE", message: "Agent delegation relationships must form an acyclic graph." } };
  }
  return { workflow: { ...workflow, nodes, edges } };
}

function normalizeGraphResource(value, index) {
  if (!isRecord(value) || typeof value.type !== "string" || !["resource.agent", "resource.skill", "resource.tool", "resource.mcp", "resource.plugin"].includes(value.type)) {
    return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph resource type is unsupported." } };
  }
  if (typeof value.name !== "string" || !registryName.test(value.name)
    || (value.scope !== "project" && value.scope !== "global")
    || (value.mode !== "reference" && value.mode !== "managed")) {
    return { failure: { code: "WORKFLOW_RESOURCE_GRAPH_INVALID", message: "Agent graph resource identity or mode is invalid." } };
  }
  const allowedKeys = graphResourceAllowedKeys(value);
  if (!allowedKeys || !hasExactKeys(value, allowedKeys)) {
    return {
      failure: {
        code: "WORKFLOW_RESOURCE_GRAPH_INVALID",
        message: "Agent graph resource keys do not match its mode and type.",
        details: graphResourceShapeDetails(value, index),
      },
    };
  }
  if (containsSecretLiteral(value)) {
    return { failure: { code: "WORKFLOW_RESOURCE_SECRET_DETECTED", message: "Agent graph resource contains a possible plaintext secret." } };
  }
  return { value };
}

function graphResourceShapeDetails(value, index) {
  const details = { resourceIndex: index, keys: Object.keys(value).sort() };
  for (const key of ["type", "name", "scope", "mode"]) {
    if (typeof value[key] === "string") details[key] = value[key];
  }
  return details;
}

function graphRelationshipEndpointDetails(value, index, endpoint) {
  const details = {
    relationshipIndex: index,
    endpoint,
    keys: isRecord(value) ? Object.keys(value).sort() : [],
  };
  if (isRecord(value)) {
    for (const key of ["type", "name", "scope"]) {
      if (typeof value[key] === "string") details[key] = value[key];
    }
  }
  return details;
}

function graphResourceAllowedKeys(value) {
  const base = ["type", "name", "scope", "mode"];
  if (value.mode === "reference") return base;
  if (value.type === "resource.mcp") return [...base, "config"];
  if (value.type === "resource.plugin") {
    if (typeof value.content === "string" && value.config === undefined) return [...base, "content"];
    if (value.content === undefined && isRecord(value.config)) return [...base, "config"];
    return undefined;
  }
  if (value.type === "resource.skill" && value.files !== undefined) return [...base, "content", "files"];
  return [...base, "content"];
}

function graphResourceData(value) {
  return Object.fromEntries(Object.entries(value).filter(([key]) => key !== "type"));
}

function normalizeGraphIdentity(value) {
  if (!isRecord(value) || !hasExactKeys(value, ["type", "name", "scope"]) || typeof value.type !== "string"
    || !["resource.agent", "resource.skill", "resource.tool", "resource.mcp", "resource.plugin"].includes(value.type)
    || typeof value.name !== "string" || !registryName.test(value.name)
    || (value.scope !== "project" && value.scope !== "global")) {
    return { failure: true };
  }
  return { value };
}

function graphResourceIdentity(value) {
  return `${value.scope}:${value.type}:${value.name}`;
}

function graphNodeIdentity(node) {
  if (!isRecord(node) || typeof node.type !== "string" || !isRecord(node.data)
    || typeof node.data.name !== "string" || (node.data.scope !== "project" && node.data.scope !== "global")) return undefined;
  return graphResourceIdentity({ type: node.type, name: node.data.name, scope: node.data.scope });
}

function findInventoryResource(inventory, resource) {
  const group = resource.type === "resource.agent" ? "agents"
    : resource.type === "resource.tool" ? "tools"
      : resource.type === "resource.skill" ? "skills"
        : resource.type === "resource.plugin" ? "plugins" : "mcp";
  return inventory.resources[group].find((candidate) => isRecord(candidate)
    && candidate.type === resource.type && candidate.name === resource.name && candidate.scope === resource.scope);
}

function hasInventorySources(resource) {
  return Array.isArray(resource.sources)
    && resource.sources.length > 0
    && resource.sources.every((source) => source === "config" || source === "registry" || source === "runtime");
}

function hasExplicitGraphResourceIntent(request, name) {
  if (typeof request !== "string") return false;
  const exactName = new RegExp(`(?:^|[^A-Za-z0-9_-])${escapeRegExp(name)}(?=$|[^A-Za-z0-9_-])`);
  return exactName.test(request)
    && /\b(?:use|reuse|attach|connect|bind|reference|delegate|add|include)\b|使用|重用|連接|綁定|引用|參照|委派|新增|加入/i.test(request);
}

function hasExplicitManagedGraphResourceIntent(request, name, existing) {
  if (typeof request !== "string") return false;
  const exactName = new RegExp(`(?:^|[^A-Za-z0-9_-])${escapeRegExp(name)}(?=$|[^A-Za-z0-9_-])`);
  if (!exactName.test(request)) return false;
  const verbs = existing
    ? /\b(?:update|edit|modify|change|replace|configure|set|manage)\b|更新|修改|變更|替換|設定|管理/i
    : /\b(?:add|create|build|generate|make|include|manage|delegate)\b|新增|建立|產生|加入|管理|委派/i;
  return verbs.test(request);
}

function hasDelegationCycle(nodes, edges) {
  const adjacency = new Map();
  for (const edge of edges) {
    if (edge.kind !== "delegation") continue;
    adjacency.set(edge.source, [...(adjacency.get(edge.source) ?? []), edge.target]);
  }
  const visiting = new Set();
  const visited = new Set();
  const visit = (nodeID) => {
    if (visiting.has(nodeID)) return true;
    if (visited.has(nodeID)) return false;
    visiting.add(nodeID);
    for (const child of adjacency.get(nodeID) ?? []) {
      if (visit(child)) return true;
    }
    visiting.delete(nodeID);
    visited.add(nodeID);
    return false;
  };
  return nodes.some((node) => visit(node.id));
}

function hasExplicitSkillReferenceIntent(request, name) {
  if (typeof request !== "string") return false;
  const escapedName = escapeRegExp(name);
  const exactName = new RegExp(`(?:^|[^A-Za-z0-9_-])${escapedName}(?=$|[^A-Za-z0-9_-])`);
  return exactName.test(request) && /\b(?:existing|use|reuse|attach|connect|reference|catalog|existing\s+skill)\b|既有|現有|使用|重用|連接|綁定|引用|參照/i.test(request);
}

async function fetchSessionInventory(project, context) {
  if (!context || typeof context.sessionID !== "string" || !context.sessionID.trim()) {
    return { failure: { code: "WORKFLOW_RESOURCE_REFERENCE_CONTEXT_INVALID", message: "Existing Skill references require a session-bound inventory context." } };
  }
  try {
    const baseURL = (typeof process !== "undefined" && process.env.AGENT_SYSTEM_BFF_BASE_URL || DEFAULT_BFF_BASE_URL).replace(/\/+$/, "");
    const endpoint = new URL(`/bff/workflow-resources/test-chat/${encodeURIComponent(context.sessionID)}/inventory`, baseURL);
    endpoint.searchParams.set("project", project);
    const response = await fetch(endpoint, {
      headers: { "x-agent-system-workspace": project },
      signal: AbortSignal.timeout(15_000),
    });
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || !isRecord(payload) || payload.project !== project || payload.includeGlobal !== true
      || !isRecord(payload.resources) || !inventoryGroups.every((group) => Array.isArray(payload.resources[group]))
      || !Array.isArray(payload.warnings)) {
      return { failure: { code: "WORKFLOW_RESOURCE_REFERENCE_CONTEXT_INVALID", message: "Backend did not return a valid session-bound resource inventory." } };
    }
    return { inventory: payload };
  } catch {
    return { failure: { code: "WORKFLOW_RESOURCE_REFERENCE_CONTEXT_INVALID", message: "Session-bound resource inventory is unavailable." } };
  }
}

function validateTool(content) {
  if (!/\bexport\s+default\s*\{/.test(content)
    || !/\binput\s*:\s*\{\s*type\s*:\s*["']object["']/.test(content)
    || !/\bproperties\s*:/.test(content)
    || !/\bexecute\s*\(/.test(content)) {
    return { code: "WORKFLOW_RESOURCE_CONTENT_INVALID", message: "Tool content must export a native V2 Tool with bounded JSON Schema input and execute." };
  }
  return undefined;
}

function validateMcp(config) {
  if (!isRecord(config)) return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "MCP config must be an object." };
  if (config.type === "remote") {
    if (!hasOnlyKeys(config, ["type", "url", "headers", "oauth", "enabled", "timeout"])
      || typeof config.url !== "string" || !/^https?:\/\/[^\s]+$/i.test(config.url)
      || (config.headers !== undefined && !isRecord(config.headers))
      || (config.oauth !== undefined && !isRecord(config.oauth))) {
      return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "Remote MCP config is invalid." };
    }
  } else if (config.type === "local") {
    if (!hasOnlyKeys(config, ["type", "command", "cwd", "environment", "enabled", "timeout"])
      || !Array.isArray(config.command) || config.command.length < 1 || config.command.length > 100
      || !config.command.every((part) => typeof part === "string" && part.trim())
      || (config.cwd !== undefined && (typeof config.cwd !== "string" || hasControlCharacter(config.cwd)))
      || (config.environment !== undefined && !isRecord(config.environment))) {
      return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "Local MCP config is invalid." };
    }
  } else {
    return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "MCP type must be remote or local." };
  }
  if (config.enabled !== undefined && typeof config.enabled !== "boolean") {
    return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "MCP enabled must be boolean." };
  }
  if (config.timeout !== undefined && (!Number.isInteger(config.timeout) || config.timeout < 1 || config.timeout > 600000)) {
    return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "MCP timeout is invalid." };
  }
  return undefined;
}

function validateRemotePlugin(config, request) {
  if (!isRecord(config) || !hasExactKeys(config, ["entry"])
    || typeof config.entry !== "string" || !config.entry.trim()
    || config.entry.length > 300 || hasControlCharacter(config.entry)) {
    return { code: "WORKFLOW_RESOURCE_CONFIG_INVALID", message: "Remote Plugin config must contain one bounded entry." };
  }
  if (typeof request !== "string" || !request.includes(config.entry)) {
    return { code: "WORKFLOW_RESOURCE_PLUGIN_OWNERSHIP_INVALID", message: "Remote Plugin entry must be explicitly present in the request." };
  }
  return undefined;
}

function validateTaskPolicy(lines, children) {
  const tools = mapEntries(lines, "tools");
  const permissions = mapEntries(lines, "permission");
  const taskTool = tools.find((entry) => entry.key === "task");
  const taskPermission = permissions.find((entry) => entry.key === "task");
  const taskChildren = nestedMapEntries(lines, "permission", "task");
  const expected = new Set(children);
  if (expected.size === 0) {
    if (taskTool?.value === "true" || taskPermission?.value !== "deny" || taskChildren.length > 0) {
      return "Leaf Agent must explicitly deny task in permission.";
    }
    return undefined;
  }
  if (taskTool?.value !== "true" || taskPermission?.value !== "") return "Delegating Agent must use a nested task allowlist.";
  if (hasDuplicateKeys(taskChildren)
    || taskChildren.length !== expected.size + 1
    || taskChildren[0]?.key !== "*"
    || taskChildren[0]?.value !== "deny") {
    return "Delegating Agent task allowlist must deny unspecified children.";
  }
  for (const entry of taskChildren) {
    if (entry.key === "*") continue;
    if (!expected.has(entry.key) || entry.value !== "allow") return "Agent task allowlist contains a non-child or non-allow entry.";
  }
  for (const child of expected) {
    if (!taskChildren.some((entry) => entry.key === child && entry.value === "allow")) return "Agent task allowlist omits a direct child.";
  }
  return undefined;
}

function validateAgentPermissions(frontmatter, workflow, target, childNames, generatedSkillNames = []) {
  const tools = mapEntries(frontmatter.lines, "tools");
  const permissions = mapEntries(frontmatter.lines, "permission");
  const toolWildcards = tools.filter((entry) => entry.key === "*");
  const permissionWildcards = permissions.filter((entry) => entry.key === "*");
  if (hasDuplicateKeys(tools) || hasDuplicateKeys(permissions)
    || tools.some((entry) => !["", "true", "false"].includes(entry.value))
    || permissions.some((entry) => !["", "allow", "deny", "ask"].includes(entry.value))
    || toolWildcards.length !== 1 || tools[0]?.key !== "*" || tools[0]?.value !== "false"
    || !tools.some((entry) => entry.key === "error_log_recent" && entry.value === "true")
    || !permissions.some((entry) => entry.key === "error_log_recent" && entry.value === "allow")) {
    return "Agent content does not satisfy the minimum diagnostic permission policy.";
  }
  if (permissionWildcards.length > 1
    || (permissionWildcards.length === 1 && (permissions[0]?.key !== "*" || permissions[0]?.value !== "deny"))) {
    return "Agent permission wildcard must be a single leading deny rule.";
  }
  if (!frontmatter.body.includes("error_log_recent")
    || !/(?:error|failure|錯誤|失敗)/i.test(frontmatter.body)
    || !/(?:call|invoke|呼叫|调用)/i.test(frontmatter.body)) {
    return "Agent instructions must call error_log_recent before returning an error.";
  }

  const allowedTools = new Set(["error_log_recent"]);
  const allowedPermissions = new Set(["error_log_recent"]);
  const requiredTools = new Set(["error_log_recent"]);
  const requiredPermissions = new Set(["error_log_recent"]);
  if (childNames.length > 0) {
    allowedTools.add("task");
    allowedPermissions.add("task");
  }
  const skillNames = [];
  for (const edge of workflow.edges) {
    if (!isRecord(edge) || edge.kind !== "capability" || edge.target !== target.id || edge.targetHandle !== "capability") continue;
    const source = workflow.nodes.find((node) => isRecord(node) && node.id === edge.source);
    if (!isRecord(source) || !isRecord(source.data) || typeof source.data.name !== "string") continue;
    if (source.type === "resource.tool") {
      allowedTools.add(source.data.name);
      allowedPermissions.add(source.data.name);
      requiredTools.add(source.data.name);
      requiredPermissions.add(source.data.name);
    } else if (source.type === "resource.mcp") {
      const namespace = source.data.name + "_*";
      allowedTools.add(namespace);
      allowedPermissions.add(namespace);
      requiredTools.add(namespace);
      requiredPermissions.add(namespace);
    } else if (source.type === "resource.skill") {
      skillNames.push(source.data.name);
      allowedTools.add("skill");
      allowedPermissions.add("skill");
      requiredTools.add("skill");
    }
  }
  skillNames.push(...generatedSkillNames);
  if (generatedSkillNames.length > 0) {
    allowedTools.add("skill");
    allowedPermissions.add("skill");
    requiredTools.add("skill");
  }
  for (const entry of tools) {
    if (entry.value === "true" && !allowedTools.has(entry.key)) return `Agent tools cannot enable unconnected capability ${entry.key}.`;
  }
  for (const entry of permissions) {
    if ((entry.value === "allow" || entry.value === "ask") && !allowedPermissions.has(entry.key)) {
      return `Agent permission cannot enable unconnected capability ${entry.key}.`;
    }
  }
  for (const key of requiredTools) {
    if (!tools.some((entry) => entry.key === key && entry.value === "true")) return `Agent tools must enable direct capability ${key}.`;
  }
  for (const key of requiredPermissions) {
    if (!permissions.some((entry) => entry.key === key && entry.value === "allow")) return `Agent permission must allow direct capability ${key}.`;
  }
  const skillPermission = permissions.find((entry) => entry.key === "skill");
  const skillEntries = nestedMapEntries(frontmatter.lines, "permission", "skill");
  if (skillNames.length === 0) {
    if (tools.some((entry) => entry.key === "skill" && entry.value === "true") || skillPermission || skillEntries.length > 0) {
      return "Agent cannot enable an unconnected Skill.";
    }
  } else {
    const expectedSkills = new Set(skillNames);
    if (skillPermission?.value !== ""
      || hasDuplicateKeys(skillEntries)
      || skillEntries.length !== expectedSkills.size + 1
      || skillEntries[0]?.key !== "*"
      || skillEntries[0]?.value !== "deny") {
      return "Agent Skill permission must be an exact deny-by-default direct capability allowlist.";
    }
    for (const entry of skillEntries) {
      if (entry.key === "*") continue;
      if (!expectedSkills.has(entry.key) || entry.value !== "allow") return "Agent Skill permission contains an unconnected capability.";
    }
    for (const skill of expectedSkills) {
      if (!skillEntries.some((entry) => entry.key === skill && entry.value === "allow")) return "Agent Skill permission omits a direct Skill.";
    }
  }
  return undefined;
}

function resourceShapeKeys(resourceType, resource) {
  if (resourceType === "mcp") return ["name", "scope", "config"];
  if (resourceType === "plugin") {
    if (resource.content !== undefined && resource.config === undefined) return ["name", "scope", "content"];
    if (resource.config !== undefined && resource.content === undefined) return ["name", "scope", "config"];
    return undefined;
  }
  if (resourceType === "skill" && resource.files !== undefined) return ["name", "scope", "content", "files"];
  return ["name", "scope", "content"];
}

function parseFrontmatter(content) {
  const match = content.match(/^---\s*\r?\n([\s\S]*?)\r?\n---(?:\s*\r?\n|$)/);
  if (!match) return undefined;
  return { lines: match[1].split(/\r?\n/), body: content.slice(match[0].length) };
}

function scalar(lines, key) {
  const pattern = new RegExp("^" + escapeRegExp(key) + ":\\s*(.*?)\\s*$");
  const matches = lines.filter((candidate) => leadingSpaces(candidate) === 0 && pattern.test(candidate));
  if (matches.length !== 1) return "";
  return simpleScalar(matches[0].match(pattern)?.[1] ?? "");
}

function simpleScalar(value) {
  const trimmed = value.trim();
  if (!trimmed || /\s+#/.test(trimmed) || /^(?:#|\[|\{|&|\*|!|\||>|@|,|\}|\]|%|`|[-?:](?:\s|$))/.test(trimmed)) return "";
  if (trimmed.startsWith('"')) {
    try {
      const parsed = JSON.parse(trimmed);
      return typeof parsed === "string" && !hasControlCharacter(parsed) ? parsed : "";
    } catch {
      return "";
    }
  }
  if (trimmed.startsWith("'")) {
    if (trimmed.length < 2 || !trimmed.endsWith("'")) return "";
    const inner = trimmed.slice(1, -1);
    let result = "";
    for (let index = 0; index < inner.length; index += 1) {
      if (inner[index] !== "'") {
        result += inner[index];
        continue;
      }
      if (inner[index + 1] !== "'") return "";
      result += "'";
      index += 1;
    }
    return hasControlCharacter(result) ? "" : result;
  }
  if (/:\s|:$/.test(trimmed) || /^(?:null|~|true|false|yes|no|on|off|[-+]?\d+(?:\.\d+)?)$/i.test(trimmed)) return "";
  return trimmed;
}

function currentScalar(lines, key) {
  const pattern = new RegExp("^" + escapeRegExp(key) + ":\\s*(.*?)\\s*$");
  const matches = lines.filter((candidate) => leadingSpaces(candidate) === 0 && pattern.test(candidate));
  if (matches.length === 0) return { valid: true, value: "" };
  if (matches.length !== 1) return { valid: false, value: "" };
  const value = simpleScalar(stripInlineComment(matches[0].match(pattern)?.[1] ?? ""));
  return { valid: Boolean(value), value };
}

function stripInlineComment(value) {
  let quote = "";
  let escaped = false;
  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];
    if (quote) {
      if (!escaped && character === quote) quote = "";
      escaped = quote === '"' && !escaped && character === "\\";
      if (character !== "\\") escaped = false;
      continue;
    }
    if (character === '"' || character === "'") quote = character;
    else if (character === "#" && (index === 0 || /\s/.test(value[index - 1]))) return value.slice(0, index).trimEnd();
  }
  return value;
}

function hasAmbiguousScalarFields(lines, keys) {
  return keys.some((key) => {
    const escaped = escapeRegExp(key);
    const pattern = new RegExp(`^(?:${escaped}|"${escaped}"|'${escaped}')\\s*:`);
    return lines.filter((line) => leadingSpaces(line) === 0 && pattern.test(line.trim())).length > 1;
  });
}

function hasUnsupportedYamlSyntax(lines) {
  return lines.some((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) return false;
    if (/^(?:\?|:\s|<<\s*:)/.test(trimmed)) return true;
    if (leadingSpaces(line) !== 0) return false;
    if (!/^[A-Za-z][A-Za-z0-9_-]*:/.test(trimmed)) return true;
    const scalarMatch = trimmed.match(/^[A-Za-z][A-Za-z0-9_-]*:\s*(.+)$/);
    const supportedBooleanAgentFlag = /^(?:disabled|disable):\s*(?:true|false)\s*(?:#.*)?$/i.test(trimmed);
    return Boolean(scalarMatch && !simpleScalar(scalarMatch[1]) && !supportedBooleanAgentFlag);
  });
}

function mapEntries(lines, mapName) {
  const block = mapBlock(lines, mapName);
  if (!block) return [];
  if (block.invalid) return [{ key: "[INVALID]", value: "[INVALID]" }];
  const entries = [];
  for (let index = block.start + 1; index < block.end; index += 1) {
    const line = lines[index] ?? "";
    if (!line.trim() || line.trim().startsWith("#")) continue;
    if (leadingSpaces(line) !== 2) continue;
    const match = line.trim().match(/^(?:"([^"]+)"|'([^']+)'|([A-Za-z0-9_.-]+)):\s*(.*?)\s*$/);
    if (!match) return [{ key: "[INVALID]", value: "[INVALID]" }];
    const key = match[1] ?? match[2] ?? match[3];
    if (key.includes("\\")) return [{ key: "[INVALID]", value: "[INVALID]" }];
    entries.push({ key, value: unquote(match[4]) });
  }
  return entries;
}

function nestedMapEntries(lines, mapName, parentKey) {
  const block = mapBlock(lines, mapName);
  if (!block) return [];
  if (block.invalid) return [{ key: "[INVALID]", value: "[INVALID]" }];
  const parentPattern = new RegExp(`^(?:${escapeRegExp(parentKey)}|"${escapeRegExp(parentKey)}"|'${escapeRegExp(parentKey)}')\\s*:`);
  const parentIndexes = lines.flatMap((line, index) => index > block.start && index < block.end
    && leadingSpaces(line) === 2 && parentPattern.test(line.trim()) ? [index] : []);
  if (parentIndexes.length === 0) return [];
  if (parentIndexes.length !== 1) return [{ key: "[INVALID]", value: "[INVALID]" }];
  const parentIndex = parentIndexes[0];
  if (lines[parentIndex].trim() !== parentKey + ":") {
    return lines[parentIndex].trim().startsWith(parentKey + ":") ? [] : [{ key: "[INVALID]", value: "[INVALID]" }];
  }
  const entries = [];
  for (let index = parentIndex + 1; index < block.end; index += 1) {
    const line = lines[index] ?? "";
    if (line.trim() && leadingSpaces(line) <= 2) break;
    if (!line.trim() || line.trim().startsWith("#")) continue;
    if (leadingSpaces(line) !== 4) continue;
    const match = line.trim().match(/^(?:"([^"]+)"|'([^']+)'|([A-Za-z0-9_.-]+)):\s*(.*?)\s*$/);
    if (!match) return [{ key: "[INVALID]", value: "[INVALID]" }];
    const key = match[1] ?? match[2] ?? match[3];
    if (key.includes("\\")) return [{ key: "[INVALID]", value: "[INVALID]" }];
    entries.push({ key, value: unquote(match[4]) });
  }
  return entries;
}

function mapBlock(lines, mapName) {
  const escaped = escapeRegExp(mapName);
  const pattern = new RegExp(`^(?:${escaped}|"${escaped}"|'${escaped}')\\s*:`);
  const starts = lines.flatMap((line, index) => leadingSpaces(line) === 0 && pattern.test(line.trim()) ? [index] : []);
  if (starts.length === 0) return undefined;
  const start = starts[0];
  if (starts.length !== 1 || lines[start].trim() !== mapName + ":") return { start, end: start + 1, invalid: true };
  let end = lines.length;
  for (let index = start + 1; index < lines.length; index += 1) {
    if (lines[index].trim() && leadingSpaces(lines[index]) === 0) {
      end = index;
      break;
    }
  }
  return { start, end, invalid: false };
}

function hasDuplicateKeys(entries) {
  return new Set(entries.map((entry) => entry.key)).size !== entries.length;
}

function containsSecretLiteral(value, key = "", headerContext = false) {
  if (typeof value === "string") {
    if (!value || envReference.test(value)) return false;
    if (isSensitiveKey(key) || (headerContext && isSensitiveHeader(key))) return true;
    return /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(value)
      || /\b(?:Bearer|Basic)\s+[A-Za-z0-9._~+\/-]{4,}={0,2}(?=$|[^A-Za-z0-9._~+\/=-])/i.test(value)
      || /\b(?:sk|ghp|github_pat|xox[baprs])[-_][A-Za-z0-9_-]{16,}\b/.test(value)
      || /https?:\/\/[^\s/:]+:[^\s/@]+@/i.test(value)
      || containsSensitiveAssignment(value);
  }
  if (Array.isArray(value)) return value.some((item) => containsSecretLiteral(item, key, headerContext));
  if (!isRecord(value)) return false;
  const nextHeaderContext = headerContext || key.toLowerCase() === "headers";
  return Object.entries(value).some(([childKey, item]) => {
    if ((isSensitiveKey(childKey) || (nextHeaderContext && isSensitiveHeader(childKey))) && typeof item !== "string") return true;
    return containsSecretLiteral(item, childKey, nextHeaderContext);
  });
}

function boundedDiagnostics(value) {
  let remaining = 20000;
  const visit = (item, key = "", depth = 0) => {
    if (remaining <= 0 || depth > 8) return "[TRUNCATED]";
    if (key && isSensitiveKey(key)) return "[REDACTED]";
    if (typeof item === "string") {
      const text = redactDiagnostic(item).slice(0, Math.min(500, remaining));
      remaining -= text.length;
      return text;
    }
    if (Array.isArray(item)) {
      const result = [];
      for (const entry of item.slice(0, 20)) {
        if (remaining <= 0) break;
        result.push(visit(entry, key, depth + 1));
      }
      return result;
    }
    if (isRecord(item)) {
      const result = {};
      for (const [childKey, entry] of Object.entries(item).slice(0, 50)) {
        if (remaining <= 0) break;
        const outputKey = boundedDiagnosticKey(childKey);
        remaining -= Math.min(outputKey.length, remaining);
        result[outputKey] = visit(entry, childKey, depth + 1);
      }
      return result;
    }
    remaining -= Math.min(String(item).length, remaining);
    return item;
  };
  return visit(value);
}

function redactDiagnostic(value) {
  if (/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(value)) return "[REDACTED PRIVATE KEY]";
  const tokensRedacted = value
    .replace(/(https?:\/\/)[^\s/:]+:[^\s/@]+@/gi, "$1[REDACTED]@")
    .replace(/\b(Bearer|Basic)\s+[A-Za-z0-9._~+\/-]{4,}={0,2}(?=$|[^A-Za-z0-9._~+\/=-])/gi, "$1 [REDACTED]")
    .replace(/\b(?:sk|ghp|github_pat|xox[baprs])[-_][A-Za-z0-9_-]{16,}\b/g, "[REDACTED TOKEN]");
  return redactSensitiveAssignments(tokensRedacted);
}

function boundedDiagnosticKey(value) {
  return redactDiagnostic(value).slice(0, 200) || "[EMPTY KEY]";
}

function redactSensitiveAssignments(value) {
  return redactAssignmentForm(redactAssignmentForm(value, true), false);
}

function redactAssignmentForm(value, quoted) {
  const pattern = quoted
    ? /(["'])([A-Za-z][A-Za-z0-9_. -]{0,80})\1(\s*[:=]\s*)/g
    : /(^|[^A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_. -]{0,80}?)(\s*[:=]\s*)/g;
  let output = "";
  let cursor = 0;
  for (let match = pattern.exec(value); match; match = pattern.exec(value)) {
    const key = match[2] ?? "";
    if (!isSensitiveDiagnosticKey(key)) {
      pattern.lastIndex = match.index + Math.max(match[1]?.length ?? 0, 1);
      continue;
    }
    const valueStart = pattern.lastIndex;
    const valueEnd = assignmentValueEnd(value, valueStart);
    output += value.slice(cursor, valueStart) + "[REDACTED]";
    cursor = valueEnd;
    pattern.lastIndex = valueEnd;
  }
  return output ? output + value.slice(cursor) : value;
}

function assignmentValueEnd(value, start) {
  if (value.startsWith("[REDACTED]", start)) return start + "[REDACTED]".length;
  const quote = value[start];
  if (quote === '"' || quote === "'") {
    let escaped = false;
    for (let index = start + 1; index < value.length; index += 1) {
      const character = value[index];
      if (!escaped && character === quote) return index + 1;
      escaped = !escaped && character === "\\";
      if (character !== "\\") escaped = false;
    }
    return value.length;
  }
  if (quote === "{" || quote === "[") {
    const closing = quote === "{" ? "}" : "]";
    let depth = 0;
    let stringQuote = "";
    let escaped = false;
    for (let index = start; index < value.length; index += 1) {
      const character = value[index];
      if (stringQuote) {
        if (!escaped && character === stringQuote) stringQuote = "";
        escaped = !escaped && character === "\\";
        if (character !== "\\") escaped = false;
        continue;
      }
      if (character === '"' || character === "'") stringQuote = character;
      else if (character === quote) depth += 1;
      else if (character === closing && --depth === 0) return index + 1;
    }
    return value.length;
  }
  let end = start;
  while (end < value.length && !/[\r\n,;}\]"']/.test(value[end])) end += 1;
  return end;
}

function failure(code, message, details = []) {
  return {
    content: JSON.stringify({ error: { code, message, details: boundedDiagnostics(details) } }),
    metadata: { title: code },
  };
}

function normalizeResourceType(value) {
  return typeof value === "string" ? value.replace(/^resource\./, "").trim() : undefined;
}

function hasExactKeys(value, expected) {
  return isRecord(value)
    && JSON.stringify(Object.keys(value).sort()) === JSON.stringify([...expected].sort());
}

function hasRequiredKeys(value, required) {
  return isRecord(value) && required.every((key) => Object.prototype.hasOwnProperty.call(value, key));
}

function hasOnlyKeys(value, allowed) {
  return isRecord(value) && Object.keys(value).every((key) => allowed.includes(key));
}

function isStringArray(value) {
  return Array.isArray(value) && value.length <= 200 && value.every((item) => typeof item === "string");
}

function isSensitiveKey(key) {
  const compact = key.replace(/[^A-Za-z0-9]/g, "").toLowerCase();
  return /(?:apikey|accesstoken|refreshtoken|token|secret|secretkey|password|passwd|authorization|proxyauthorization|credential|clientsecret|privatekey|cookie|setcookie)$/.test(compact);
}

function isSensitiveDiagnosticKey(key) {
  return isSensitiveKey(key) || /^(?:environment|env|stack)$/i.test(key);
}

function containsSensitiveAssignment(value) {
  for (const match of value.matchAll(/(["'])([A-Za-z][A-Za-z0-9_. -]{0,80})\1\s*[:=]/g)) {
    if (isSensitiveKey(match[2] ?? "") && !hasEnvReferenceAt(value, match.index + match[0].length)) return true;
  }
  for (const match of value.matchAll(/(^|[^A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_. -]{0,80}?)\s*[:=]/g)) {
    if (isSensitiveKey(match[2] ?? "") && !hasEnvReferenceAt(value, match.index + match[0].length)) return true;
  }
  return false;
}

function hasEnvReferenceAt(value, start) {
  const remaining = value.slice(start).trimStart();
  return /^\{env:[A-Z_][A-Z0-9_]*\}(?:[.,;)}\]]?[ \t]*)(?:\r?\n|$)/.test(remaining)
    || /^(["'])\{env:[A-Z_][A-Z0-9_]*\}\1(?:[.,;)}\]]?[ \t]*)(?:\r?\n|$)/.test(remaining);
}

function isSensitiveHeader(key) {
  return /^(?:authorization|proxy-authorization|cookie|set-cookie|x-api-key|api-key)$/i.test(key);
}

function hasControlCharacter(value) {
  return /[\u0000-\u001f\u007f]/.test(value);
}

function leadingSpaces(value) {
  return value.length - value.trimStart().length;
}

function unquote(value) {
  if (value.length >= 2 && ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'")))) {
    return value.slice(1, -1);
  }
  return value;
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
